function main(): void {
  let n = 0;
  const id = setInterval(() => {
    n++;
    console.log("tick " + n);
    if (n === 3) { clearInterval(id); console.log("cleared"); }
  }, 5);
  const gone = setTimeout(() => console.log("never"), 3);
  clearTimeout(gone);
  const imm = setImmediate(() => console.log("never imm"));
  clearImmediate(imm);
}
